const http=require('http');const crypto=require('crypto');const {URL}=require('url');
const publicPort=Number(process.env.PORT||10000);const internalPort=publicPort+1;process.env.PORT=String(internalPort);require('./server.js');
const BUILD_VERSION='8.6.0';const SECRET=process.env.XSPORTSX_CONFIG_SECRET||'change-this-xsportsx-secret-in-render';const KEY=crypto.createHash('sha256').update(SECRET).digest();const RESOURCES=new Set(['manifest.json','catalog','meta','stream']);const PUBLIC=new Set(['configure','health','xtream-health','artwork','qr']);
const LEAGUES={nfl:['NFL','🏈'],ncaaf:['NCAA Football','🏈'],nba:['NBA','🏀'],wnba:['WNBA','🏀'],ncaab:['NCAA Basketball','🏀'],mlb:['MLB','⚾'],nhl:['NHL','🏒'],mls:['MLS','⚽'],epl:['Premier League','⚽'],ucl:['UEFA Champions League','⚽'],laliga:['LaLiga','⚽'],seriea:['Serie A','⚽'],bundesliga:['Bundesliga','⚽'],ligue1:['Ligue 1','⚽'],ufc:['UFC','🥊'],boxing:['Boxing','🥊']};
function encrypt(c){const iv=crypto.randomBytes(12),x=crypto.createCipheriv('aes-256-gcm',KEY,iv);const body=Buffer.concat([x.update(JSON.stringify(c),'utf8'),x.final()]);return [iv,x.getAuthTag(),body].map(b=>b.toString('base64url')).join('.')}
function decrypt(t){try{const[a,b,c]=String(t||'').split('.');if(!a||!b||!c)return null;const x=crypto.createDecipheriv('aes-256-gcm',KEY,Buffer.from(a,'base64url'));x.setAuthTag(Buffer.from(b,'base64url'));return JSON.parse(Buffer.concat([x.update(Buffer.from(c,'base64url')),x.final()]).toString())}catch{return null}}
function selected(t){const c=decrypt(t);return new Set(Array.isArray(c?.sports)?c.sports.map(String).filter(x=>LEAGUES[x]):[])}
function base(req){return `${String(req.headers['x-forwarded-proto']||'https').split(',')[0]}://${req.headers.host||'localhost'}`}
function manifest(req,t){const s=selected(t);return{id:`community.xsportsx.v8.6.${crypto.createHash('sha256').update(t).digest('hex').slice(0,16)}`,version:BUILD_VERSION,name:'XSportsX',description:'XSportsX private sports connection',resources:[{name:'catalog',types:['tv']},{name:'meta',types:['tv']},{name:'stream',types:['tv']}],types:['tv'],idPrefixes:['sport:'],catalogs:[...s].map(id=>({type:'tv',id,name:`${LEAGUES[id][1]} ${LEAGUES[id][0]}`,extra:[],showInHome:true})),behaviorHints:{configurable:false,configurationRequired:false},logo:`${base(req)}/artwork/other.svg`}}
function page(){const groups=[['FOOTBALL',['nfl','ncaaf']],['BASKETBALL',['nba','wnba','ncaab']],['BASEBALL / HOCKEY',['mlb','nhl']],['SOCCER',['mls','epl','ucl','laliga','seriea','bundesliga','ligue1']],['COMBAT',['ufc','boxing']]];let cards='';for(const[g,ids]of groups){cards+=`<h3>${g}</h3>`;for(const id of ids)cards+=`<div class="row" data-id="${id}"><span>${LEAGUES[id][1]} ${LEAGUES[id][0]}</span><button type="button" class="pick" aria-pressed="false">SELECT</button></div>`}return `<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>XSportsX 8.6</title><style>body{margin:0;background:#050810;color:#fff;font:16px Arial,sans-serif}main{max-width:720px;margin:auto;padding:18px}.card{background:#0c1421;border:1px solid #26364d;border-radius:16px;padding:18px;margin:12px 0}.row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px;margin:7px 0;background:#111c2c;border:1px solid #2a3b55;border-radius:10px}.pick{min-width:82px;padding:11px;border:1px solid #53647d;border-radius:9px;background:#182438;color:#fff;font-weight:800}.pick.on{background:#e51f38;border-color:#e51f38}.count{font-weight:900;font-size:19px;margin:10px 0}.tool{padding:11px 15px;margin-right:6px;border:1px solid #40526d;border-radius:9px;background:#162238;color:#fff;font-weight:800}.create{width:100%;padding:15px;margin-top:12px;border:0;border-radius:10px;background:#e51f38;color:#fff;font-weight:900}.create:disabled{opacity:.45}.fields input{width:100%;padding:13px;margin:5px 0;box-sizing:border-box;background:#070c14;border:1px solid #34465f;border-radius:9px;color:#fff}</style></head><body><main><div class="card"><h1>XSportsX</h1><small>BUILD ${BUILD_VERSION} • SIMPLE SELECT</small></div><div class="card"><h2>Xtream Source</h2><div class="fields"><input id="base" placeholder="Server URL"><input id="user" placeholder="Username"><input id="pass" type="password" placeholder="Password"></div></div><div class="card"><h2>Choose Leagues</h2><div id="count" class="count">0 selected</div><button id="all" class="tool" type="button">SELECT ALL</button><button id="none" class="tool" type="button">CLEAR</button>${cards}<button id="create" class="create" type="button" disabled>CREATE CONNECTION</button><div id="out"></div></div></main><script>
const rows=[...document.querySelectorAll('.row')],buttons=[...document.querySelectorAll('.pick')],count=document.getElementById('count'),create=document.getElementById('create');function refresh(){const n=rows.filter(r=>r.dataset.selected==='1').length;count.textContent=n+' selected';create.disabled=!n;buttons.forEach((b,i)=>{const on=rows[i].dataset.selected==='1';b.className='pick'+(on?' on':'');b.textContent=on?'SELECTED':'SELECT';b.setAttribute('aria-pressed',on?'true':'false')})}buttons.forEach((b,i)=>b.addEventListener('click',()=>{rows[i].dataset.selected=rows[i].dataset.selected==='1'?'0':'1';refresh()}));document.getElementById('all').addEventListener('click',()=>{rows.forEach(r=>r.dataset.selected='1');refresh()});document.getElementById('none').addEventListener('click',()=>{rows.forEach(r=>r.dataset.selected='0');refresh()});create.addEventListener('click',async()=>{const sports=rows.filter(r=>r.dataset.selected==='1').map(r=>r.dataset.id);const out=document.getElementById('out');out.textContent='Creating…';const body={source:'xtream',sports,xtream:{baseUrl:document.getElementById('base').value,username:document.getElementById('user').value,password:document.getElementById('pass').value}};try{const r=await fetch('/configure',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)throw Error(d.error||'Configuration failed');out.innerHTML='<p><b>'+sports.length+' leagues locked</b></p><p><a style="color:#8fc5ff;word-break:break-all" href="'+d.manifestUrl+'">'+d.manifestUrl+'</a></p>'}catch(e){out.textContent=e.message}});refresh();</script></body></html>`}
function tokenFrom(raw){const u=new URL(raw||'/','http://local');let p=u.pathname.split('/').filter(Boolean);if(p[0]==='v527')p=p.slice(1);const i=p.findIndex(x=>RESOURCES.has(x)||x.startsWith('catalog')||x.startsWith('meta')||x.startsWith('stream'));if(i>0)return p[i-1];if(p.length===1&&!PUBLIC.has(p[0])&&!p[0].endsWith('.json'))return p[0];return u.searchParams.get('config')||''}
function rewrite(raw){const u=new URL(raw||'/','http://local');let p=u.pathname.split('/').filter(Boolean);if(p[0]==='v527')p=p.slice(1);const i=p.findIndex(x=>RESOURCES.has(x)||x.startsWith('catalog')||x.startsWith('meta')||x.startsWith('stream'));if(i<0){if(p.length===1&&!PUBLIC.has(p[0])&&!p[0].endsWith('.json')){u.pathname='/manifest.json';u.searchParams.set('config',p[0])}return u.pathname+(u.search||'')}const token=i>0?p[i-1]:'';u.pathname='/'+p.slice(i).join('/');if(token)u.searchParams.set('config',token);return u.pathname+(u.search||'')}
const proxy=http.createServer((req,res)=>{try{const u=new URL(req.url||'/','http://local'),path=rewrite(req.url),parsed=new URL(path,'http://local').pathname,baseUrl=base(req);if(parsed==='/configure'&&req.method==='GET'){const body=page();res.writeHead(200,{'content-type':'text/html;charset=utf-8','cache-control':'no-store','x-xsportsx-build':BUILD_VERSION});return res.end(body)}if(parsed==='/configure'&&req.method==='POST'){let raw='';req.on('data',d=>raw+=d);req.on('end',()=>{try{const c=JSON.parse(raw||'{}'),sports=Array.isArray(c.sports)?c.sports.map(String).filter(x=>LEAGUES[x]):[];if(!sports.length){res.writeHead(400,{'content-type':'application/json','cache-control':'no-store'});return res.end(JSON.stringify({error:'Select at least one league'}))}const t=encrypt({...c,sports});res.writeHead(200,{'content-type':'application/json','cache-control':'no-store','x-xsportsx-build':BUILD_VERSION});res.end(JSON.stringify({manifestUrl:`${baseUrl}/${t}/manifest.json`,selected:sports,version:BUILD_VERSION}))}catch(e){res.writeHead(400,{'content-type':'application/json'});res.end(JSON.stringify({error:'Invalid configuration'}))}});return}const token=tokenFrom(req.url);if(req.method==='GET'&&parsed==='/manifest.json'&&token){const s=selected(token);if(!s.size){res.writeHead(400,{'content-type':'application/json','cache-control':'no-store','x-xsportsx-build':BUILD_VERSION});return res.end(JSON.stringify({error:'Invalid or empty selection'}))}const body=JSON.stringify(manifest(req,token));res.writeHead(200,{'content-type':'application/json','cache-control':'no-store','x-xsportsx-build':BUILD_VERSION,'x-xsportsx-selected-leagues':JSON.stringify([...s])});return res.end(body)}const upstream=http.request({hostname:'127.0.0.1',port:internalPort,path,method:req.method,headers:{...req.headers,host:`127.0.0.1:${internalPort}`}},r=>{res.writeHead(r.statusCode||502,{...r.headers,'x-xsportsx-build':BUILD_VERSION});r.pipe(res)});upstream.on('error',e=>{res.statusCode=502;res.end(e.message)});req.pipe(upstream)}catch(e){res.statusCode=400;res.end(e.message)}});proxy.listen(publicPort,'0.0.0.0',()=>console.log('XSportsX '+BUILD_VERSION+' public '+publicPort));